+
+package fakecp
+
+import (
+	"crypto/ed25519"
+	"crypto/rand"
+	"crypto/tls"
+	"crypto/x509"
+	"encoding/pem"
+	"go/ast"
+	"go/parser"
+	"go/token"
+	"net"
+	"os"
+	"path/filepath"
+	"strconv"
+	"testing"
+	"time"
+)
+
+// T132: a Go peer can accept a protocol-less TLS connection, hiding the
+// missing h2 offer that grpc-netty rejects (wire-auth.md §4).
+func TestStartTLSNegotiatesH2(t *testing.T) {
+	keysDir := t.TempDir()
+	ipcDir := t.TempDir()
+	writeKeyPair := func(name string) ed25519.PrivateKey {
+		t.Helper()
+		pub, priv, err := ed25519.GenerateKey(rand.Reader)
+		if err != nil {
+			t.Fatal(err)
+		}
+		pkcs8, err := x509.MarshalPKCS8PrivateKey(priv)
+		if err != nil {
+			t.Fatal(err)
+		}
+		spki, err := x509.MarshalPKIXPublicKey(pub)
+		if err != nil {
+			t.Fatal(err)
+		}
+		if err := os.WriteFile(filepath.Join(keysDir, name+".priv"), pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: pkcs8}), 0600); err != nil {
+			t.Fatal(err)
+		}
+		if err := os.WriteFile(filepath.Join(keysDir, name+".pub"), pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: spki}), 0600); err != nil {
+			t.Fatal(err)
+		}
+		return priv
+	}
+	writeKeyPair("cp")
+	dpPriv := writeKeyPair("dp")
+	StartTLS(t, ipcDir, keysDir)
+	cert, err := SelfSigned(dpPriv, "stargate-dp")
+	if err != nil {
+		t.Fatal(err)
+	}
+	conn, err := net.DialTimeout("unix", filepath.Join(ipcDir, "control.sock"), 5*time.Second)
+	if err != nil {
+		t.Fatal(err)
+	}
+	tlsConn := tls.Client(conn, &tls.Config{
+		Certificates:          []tls.Certificate{cert},
+		InsecureSkipVerify:    true, //nolint:gosec // wire-auth §4: pin hook is the sole verifier
+		VerifyPeerCertificate: PinVerifier(filepath.Join(keysDir, "cp.pub")),
+		MinVersion:            tls.VersionTLS13,
+		NextProtos:            []string{"h2"},
+	})
+	defer tlsConn.Close()
+	if err := tlsConn.Handshake(); err != nil {
+		t.Fatal(err)
+	}
+	if got := tlsConn.ConnectionState().NegotiatedProtocol; got != "h2" {
+		t.Fatalf("fake CP negotiated ALPN %q, want exactly h2 (wire-auth.md §4)", got)
+	}
+	// grpc-go can insert h2 for its own transport. Inspect the fixture's
+	// tls.Config itself so this test fails if a future library default masks
+	// an omitted explicit pin (the T130 failure mode).
+	file, err := parser.ParseFile(token.NewFileSet(), "fakecp.go", nil, 0)
+	if err != nil {
+		t.Fatal(err)
+	}
+	found := false
+	ast.Inspect(file, func(node ast.Node) bool {
+		fn, ok := node.(*ast.FuncDecl)
+		if !ok || fn.Name.Name != "StartTLS" {
+			return true
+		}
+		ast.Inspect(fn.Body, func(node ast.Node) bool {
+			lit, ok := node.(*ast.CompositeLit)
+			if !ok {
+				return true
+			}
+			for _, elt := range lit.Elts {
+				kv, ok := elt.(*ast.KeyValueExpr)
+				if !ok {
+					continue
+				}
+				key, ok := kv.Key.(*ast.Ident)
+				if !ok || key.Name != "NextProtos" {
+					continue
+				}
+				protocols, ok := kv.Value.(*ast.CompositeLit)
+				if !ok || len(protocols.Elts) != 1 {
+					continue
+				}
+				value, ok := protocols.Elts[0].(*ast.BasicLit)
+				if !ok || value.Kind != token.STRING {
+					continue
+				}
+				name, err := strconv.Unquote(value.Value)
+				found = err == nil && name == "h2"
+			}
+			return true
+		})
+		return false
+	})
+	if !found {
+		t.Fatal("fake CP StartTLS must pin NextProtos to exactly [h2], independent of grpc-go defaults")
+	}
+}
diff --git a/tests/integration/stack_smoke_test.go b/tests/integration/stack_smoke_test.go
index 5e4dfd0..69b49ae 100644
--- a/tests/integration/stack_smoke_test.go
+++ b/tests/integration/stack_smoke_test.go
@@ -199,6 +199,43 @@ func TestStackSmoke(t *testing.T) {
 		t.Fatalf("no application byte through the tunnel within %s: %v — CONNECT established but the path carries no data (upstream/rendezvous broken)", t131ConnectWait, err)
 	}
 	t.Logf("OK: full path live — authenticated CONNECT through %s established and carrying application bytes", t131DPAddr)
+	_ = conn.Close()
+
+	// T132's live sibling: remove the DP's authority snapshot during a
+	// DP-only restart. With CP still running, admission must recover through
+	// exact-generation ReloadTokens re-delivery (Constitution Principle II).
+	t.Run("T132_DPOnlyRestartRecovery", func(t *testing.T) {
+		stopCtx, stopCancel := context.WithTimeout(ctx, t131ExecDead)
+		defer stopCancel()
+		if out, err := t131Compose(stopCtx, composeFile, envFile, "stop", "stargate-dp"); err != nil {
+			t.Fatalf("stop only DP: %v\n%s", err, out)
+		}
+		cp, err := t131Compose(ctx, composeFile, envFile, "ps", "--status", "running", "--quiet", "stargate-control")
+		if err != nil || len(strings.TrimSpace(string(cp))) == 0 {
+			t.Fatalf("CP must remain running during DP restart: %v\n%s", err, cp)
+		}
+		// A retained snapshot could make this probe pass without a CP push.
+		// Remove exactly the test project's DP snapshot while its process is
+		// stopped; keep the CP database and process intact.
+		clear := exec.CommandContext(ctx, "docker", "run", "--rm", "--user", "0:0",
+			"--entrypoint", "sh", "-v", t131Project+"_stargate-dp-state:/state",
+			"stargate/tor:local", "-c",
+			"test -f /state/dp-snapshot.json && rm /state/dp-snapshot.json")
+		if out, err := clear.CombinedOutput(); err != nil {
+			t.Fatalf("remove stopped DP snapshot: %v\n%s", err, out)
+		}
+		startCtx, startCancel := context.WithTimeout(ctx, t131UpDead)
+		defer startCancel()
+		if out, err := t131Compose(startCtx, composeFile, envFile, "up", "-d", "--no-deps", "stargate-dp"); err != nil {
+			t.Fatalf("restart only DP: %v\n%s", err, out)
+		}
+		cp, err = t131Compose(ctx, composeFile, envFile, "ps", "--status", "running", "--quiet", "stargate-control")
+		if err != nil || len(strings.TrimSpace(string(cp))) == 0 {
+			t.Fatalf("CP stopped during DP-only restart: %v\n%s", err, cp)
+		}
+		forwarded := t131ConnectWithRetry(t, ctx, composeFile, envFile, token)
+		_ = forwarded.Close()
+	})
 }

